// Un endpoint de alertas sin autenticar es un altavoz publico hacia el canal de
// operaciones: cualquiera puede inyectar avisos falsos o ahogar los reales.
const expected = $env.ALERT_WEBHOOK_SECRET;
if (!expected) {
  throw new Error('ALERT_WEBHOOK_SECRET no configurado: el webhook se rechaza por defecto');
}

const headers = $input.first().json.headers || {};
if (headers['x-webhook-secret'] !== expected) {
  throw new Error('Secreto de webhook invalido');
}

return [{ json: $input.first().json.body || {} }];

// Validacion de contrato antes de formatear nada.
const payload = $input.first().json;

const required = ['title', 'severity', 'message'];
const missing = required.filter((f) => !payload[f]);
if (missing.length > 0) {
  throw new Error('Faltan campos obligatorios: ' + missing.join(', '));
}

const validSeverity = ['critical', 'warning', 'info'];
if (!validSeverity.includes(payload.severity)) {
  throw new Error('Severidad invalida. Valores admitidos: ' + validSeverity.join(', '));
}

return [{ json: payload }];

// Formatea el mensaje segun severidad.
const alert = $input.first().json;

const severityConfig = {
  critical: { emoji: ':red_circle:' },
  warning: { emoji: ':warning:' },
  info: { emoji: ':information_source:' }
};
const config = severityConfig[alert.severity] || severityConfig.info;

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: config.emoji + ' ' + alert.title } },
  { type: 'section', text: { type: 'mrkdwn', text: alert.message } }
];

if (alert.fields) {
  blocks.push({
    type: 'section',
    fields: Object.entries(alert.fields).map(function (entry) {
      return { type: 'mrkdwn', text: '*' + entry[0] + ':* ' + String(entry[1]) };
    })
  });
}

if (alert.link) {
  blocks.push({
    type: 'actions',
    elements: [{
      type: 'button',
      text: { type: 'plain_text', text: 'Ver detalle' },
      url: alert.link,
      style: alert.severity === 'critical' ? 'danger' : 'primary'
    }]
  });
}

return [{ json: { blocks: blocks, text: alert.title } }];
